import java.io.ByteArrayInputStream;
import java.io.InputStream;

// Mock interfaces/classes to make the example self-contained and compile
interface IFile {}
interface IFileInfo {}
interface IProgressMonitor {}
interface IFileStore {
    void write(InputStream content, int options, IProgressMonitor monitor);
    void write(byte[] content, int options, IProgressMonitor monitor); // Must exist for the 'after' state to compile
}
class Resource {} // Unused in this specific snippet but for context

class FileSystemResourceManager {
    // These methods represent the overloaded 'write' methods available
    public void write(IFile target, InputStream content, IFileInfo fileInfo, int updateFlags, boolean append, IProgressMonitor monitor) {
        System.out.println("Writing InputStream content to " + target);
        // ... actual implementation would call store.write(content, ...)
    }
    public void write(IFile target, byte[] content, IFileInfo fileInfo, int updateFlags, boolean append, IProgressMonitor monitor) {
        System.out.println("Writing byte[] content to " + target);
        // ... actual implementation would call store.write(content, ...)
    }

    // This method demonstrates the 'before' state of the call site
    public void someMethodUsingWrite(IFile target, byte[] newContents, IFileInfo fileInfo, int updateFlags, boolean append, IProgressMonitor monitor) {
        // The pattern to match: creating ByteArrayInputStream and passing it
        write(target, new ByteArrayInputStream(newContents), fileInfo, updateFlags, append, monitor);
    }
}

