import java.io.InputStream; // ByteArrayInputStream import may be removed if not used elsewhere

// Mock interfaces/classes to make the example self-contained and compile
interface IFile {}
interface IFileInfo {}
interface IProgressMonitor {}
interface IFileStore {
    void write(InputStream content, int options, IProgressMonitor monitor);
