}
class Resource {}

class FileSystemResourceManager {
    public void write(IFile target, InputStream content, IFileInfo fileInfo, int updateFlags, boolean append, IProgressMonitor monitor) {
        System.out.println("Writing InputStream content to " + target);
    }
    public void write(IFile target, byte[] content, IFileInfo fileInfo, int updateFlags, boolean append, IProgressMonitor monitor) {
        System.out.println("Writing byte[] content to " + target);
