import java.io.ByteArrayInputStream;
import java.io.InputStream;

// Mock classes
interface IFile {}
interface IFileInfo {}
interface IProgressMonitor {}

class MyLegacyFileWriter {
    // This method ONLY has an InputStream overload and is not 'FileSystemResourceManager.write'
    public void writeDataToLegacyFile(IFile file, InputStream data, IProgressMonitor monitor) {
        System.out.println("Writing data with legacy writer to " + file);
    }
}

class AnotherComponent {
    public void processFile(IFile targetFile, byte[] rawData, IProgressMonitor monitor) {
        // This should NOT be matched by the rule because the method call is different
        new MyLegacyFileWriter().writeDataToLegacyFile(targetFile, new ByteArrayInputStream(rawData), monitor);
    }
}
